 * @returns {boolean} True if a warning should be displayed about the content
 *   of this message.
 */
async analyzeMessage(url, browser) {
  if (!url || !this.mEnabled) {
    return false;
  }

  let folder;
  try {
    const server = MailServices.accounts.findServerByURI(url);
    folder = server.getMsgFolderFromURI(null, url.spec);
  } catch (ex) {
    // findServerByURI can throw NS_ERROR_UNEXPECTED, especially if we are
    // opening an .eml file.
    if (ex.result != Cr.NS_ERROR_UNEXPECTED) {
      throw ex;
    }
  }

  if (folder) {
    // Ignore NNTP and RSS messages.
    if (folder.server.type == "nntp" || folder.server.type == "rss") {
      return false;
    }

    // Also ignore messages in Sent/Drafts/Templates/Outbox.
    const outgoingFlags =
      Ci.nsMsgFolderFlags.SentMail |
      Ci.nsMsgFolderFlags.Drafts |
      Ci.nsMsgFolderFlags.Templates |
      Ci.nsMsgFolderFlags.Queue;
    if (folder.isSpecialFolder(outgoingFlags, true)) {
      return false;
    }
  }

  // The message pane may navigate away, or go away entirely, before we get
  // here. If it has, there is no MailMessage actor to ask - getActor throws
  // for a window global which has already been swapped for a web page - and
  // there's nothing left to warn about anyway.
  let actor;
  try {
    actor =
      browser.browsingContext?.currentWindowGlobal?.getActor("MailMessage");
  } catch (ex) {
    return false;
  }
  if (!actor) {
    return false;
  }

  try {
    return await actor.sendQuery("MailMessage:AnalyzeMessageBody");
  } catch (ex) {
    // Same again, but the pane went away while the query was in flight.
    if (ex.name != "AbortError") {
      throw ex;
    }
    return false;
